'use strict';
const $=id=>document.getElementById(id),canvas=$('canvas'),ctx=canvas.getContext('2d',{alpha:false}),image=ctx.createImageData(256,240),pixels=new Uint32Array(image.data.buffer),CORE='jsnes-2.1.0';
let settings={volume:60,muted:false,crt:true,touch:matchMedia('(pointer:coarse)').matches};try{Object.assign(settings,JSON.parse(localStorage.getItem('8bit-settings')||'{}'))}catch{}
let nes=null,current=null,running=false,loading=false,db=null,slots=[],dirty=false,last=0,acc=0,frames=0,fpsTime=0,toastTimer,dragDepth=0;
let audioCtx=null,audioNode=null,gain=null,audioInit=null,samplesL=[],samplesR=[];const pressed=new Map(),applied=new Set();
function toast(s,error=false){$('toast').textContent=s;$('toast').classList.remove('hidden');$('toast').classList.toggle('error',error);clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),error?6500:3500)}
function rememberSettings(){try{localStorage.setItem('8bit-settings',JSON.stringify(settings))}catch{}}
const dbReady=new Promise((resolve,reject)=>{try{const r=indexedDB.open('drews-8bit-lounge',1);r.onupgradeneeded=()=>['roms','states','battery'].forEach(s=>r.result.createObjectStore(s,{keyPath:'id'}));r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(new Error('Storage blocked'))}catch(e){reject(e)}}).then(d=>db=d).catch(()=>toast('Browser storage is unavailable. You can play and export states, but saves cannot be kept here.',true));
async function storage(s,method,value){await dbReady;if(!db)throw new Error('Browser storage is unavailable.');return new Promise((resolve,reject)=>{const t=db.transaction(s,['get','getAll'].includes(method)?'readonly':'readwrite'),r=t.objectStore(s)[method](value);let result;r.onsuccess=()=>result=r.result;t.oncomplete=()=>resolve(result);t.onabort=t.onerror=()=>reject(t.error||new Error('Browser storage may be full.'))})}
function romId(data){const b=new Uint8Array(data);let a=2166136261,c=0x9e3779b9;for(const v of b){a=Math.imul(a^v,16777619);c=Math.imul(c^v,0x85ebca6b);c^=c>>>13}return b.length.toString(16)+'-'+(a>>>0).toString(16)+'-'+(c>>>0).toString(16)}
function validateROM(data){const b=new Uint8Array(data);if(b.length<16||b[0]!==78||b[1]!==69||b[2]!==83||b[3]!==26)throw new Error('Choose an uncompressed .nes cartridge file.');if((b[7]&12)===8)throw new Error('NES 2.0 cartridges are not supported. Use an iNES-format ROM.');if(!b[4]||b.length<16+((b[6]&4)?512:0)+b[4]*16384+b[5]*8192)throw new Error('This cartridge appears incomplete.');return (b[6]>>4)|(b[7]&240)}
