function createNES(data){const n=new jsnes.NES({sampleRate:audioCtx?.sampleRate||48000,onFrame:renderFrame,onAudioSample:(l,r)=>{if(audioNode&&running){samplesL.push(l);samplesR.push(r)}},onBatteryRamWrite:()=>dirty=true});n.loadROM(new Uint8Array(data));return n}
async function initAudio(){if(audioInit)return audioInit;audioInit=(async()=>{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw new Error();audioCtx=new AC({sampleRate:48000,latencyHint:'interactive'});await audioCtx.resume();if(audioCtx.audioWorklet){await audioCtx.audioWorklet.addModule('audio-worklet.js');audioNode=new AudioWorkletNode(audioCtx,'lounge-audio',{outputChannelCount:[2]})}else{audioNode=audioCtx.createScriptProcessor(2048,0,2);let l=[],r=[],pos=0;audioNode.port={postMessage(d){if(d.clear){l=[];r=[];pos=0;return}l.push(...d.l);r.push(...d.r);if(l.length-pos>8192)pos=l.length-4096}};audioNode.onaudioprocess=e=>{const ol=e.outputBuffer.getChannelData(0),or=e.outputBuffer.getChannelData(1);for(let i=0;i<ol.length;i++){ol[i]=l[pos]||0;or[i]=r[pos]||0;if(pos<l.length)pos++}if(pos>8192){l=l.slice(pos);r=r.slice(pos);pos=0}}}gain=audioCtx.createGain();audioNode.connect(gain).connect(audioCtx.destination);volume()})().catch(()=>toast('Sound could not start. Try reopening the player in a standalone browser tab.',true));return audioInit}
function volume(){if(gain)gain.gain.setTargetAtTime(settings.muted||!running?0:settings.volume/100,audioCtx.currentTime,.015);$('volume').value=settings.volume;$('mute').textContent=settings.muted?'♩':'♪';$('mute').setAttribute('aria-label',settings.muted?'Unmute sound':'Mute sound');$('mute').style.opacity=settings.muted?'.45':'1';rememberSettings()}
function clearAudio(){samplesL=[];samplesR=[];audioNode?.port.postMessage({clear:true})}
function release(){pressed.clear();applied.clear();if(nes)for(let p=1;p<=2;p++)for(let b=0;b<10;b++)nes.buttonUp(p,b);document.querySelectorAll('.held').forEach(e=>e.classList.remove('held'))}
function syncInput(){const wanted=new Set(pressed.values());for(const key of applied)if(!wanted.has(key)){const[p,b]=key.split(':').map(Number);nes.buttonUp(p,b);applied.delete(key)}for(const key of wanted)if(!applied.has(key)){const[p,b]=key.split(':').map(Number);nes.buttonDown(p,b);applied.add(key)}}
function playing(play){running=!!play&&!!nes;last=performance.now();acc=0;frames=0;fpsTime=last;clearAudio();release();$('pause').textContent=running?'Ⅱ':'▶';$('pause').setAttribute('aria-label',running?'Pause':'Resume');$('paused').classList.toggle('hidden',running||!nes);$('led').classList.toggle('on',!!nes);$('signal').textContent=nes?(running?'AV 1 · PLAYING':'AV 1 · PAUSED'):'AV 1 · STANDBY';$('status').textContent=nes?(running?'● PLAYING · NTSC':'● PAUSED'):'● READY WHEN YOU ARE';volume();if(running)audioCtx?.resume().catch(()=>{});else saveBattery().catch(e=>toast(e.message,true))}
function pause(){if(nes&&!loading)playing(!running)}
let padCount=-1;
function gamepads(){let pads=[];try{pads=Array.from(navigator.getGamepads?.()||[]).filter(Boolean).slice(0,2)}catch{}for(const k of [...pressed.keys()])if(k.startsWith('gp'))pressed.delete(k);pads.forEach((pad,i)=>{if(!running)return;const p=i+1;[[0,0],[1,1],[2,1],[8,2],[9,3],[12,4],[13,5],[14,6],[15,7]].forEach(([j,b])=>{if(pad.buttons[j]?.pressed)pressed.set(`gp${p}b${j}`,`${p}:${b}`)});if(pad.axes[0]<-.5)pressed.set(`gp${p}l`,`${p}:6`);if(pad.axes[0]>.5)pressed.set(`gp${p}r`,`${p}:7`);if(pad.axes[1]<-.5)pressed.set(`gp${p}u`,`${p}:4`);if(pad.axes[1]>.5)pressed.set(`gp${p}d`,`${p}:5`)});if(padCount!==pads.length){padCount=pads.length;$('pad-title').textContent=pads.length?`${pads.length} controller${pads.length>1?'s':''} connected`:'Got a controller?';$('pad-note').textContent=pads.length?'D-pad / stick · A / B · Start / Select':'Plug it in, then press a button. Two-player gamepads supported.'}}
function tick(now){gamepads();if(!running||!nes){last=now;return}acc+=Math.min(now-last,100);last=now;try{syncInput();let n=0;while(acc>=1000/60.0988&&n<6){nes.frame();acc-=1000/60.0988;n++}if(samplesL.length&&audioNode){const l=Float32Array.from(samplesL),r=Float32Array.from(samplesR);audioNode.port.postMessage({l,r},[l.buffer,r.buffer]);samplesL=[];samplesR=[]}}catch(e){playing(false);toast('Cartridge stopped: '+e.message+'. Try Reset or another ROM.',true)}if(now-fpsTime>1500){if(running)$('status').textContent=`● PLAYING · ${Math.min(60,Math.round(frames*1000/(now-fpsTime)))} FPS`;frames=0;fpsTime=now}}
function animate(now){tick(now);requestAnimationFrame(animate)}requestAnimationFrame(animate);setInterval(()=>{if(running&&performance.now()-last>24)tick(performance.now())},12);
async function saveBattery(){if(!dirty||!current||!nes?.rom.batteryRam||!db)return;const id=current.id,data=nes.cpu.mem.slice(0x6000,0x8000);dirty=false;try{await storage('battery','put',{id,data,updated:Date.now()})}catch(e){dirty=true;throw e}}
async function loadCartridge(record,remember=true){if(loading)return;loading=true;const oldRunning=running;try{await initAudio();const mapper=validateROM(record.data);await saveBattery();await dbReady;playing(false);const next=createNES(record.data),battery=db?await storage('battery','get',record.id):null;if(battery&&next.rom.batteryRam)for(let i=0;i<8192;i++)next.cpu.mem[0x6000+i]=battery.data[i]||0;nes=next;current={...record,mapper,lastPlayed:Date.now()};dirty=false;$('title').textContent=current.name;$('standby').classList.add('hidden');['pause','reset','export','import'].forEach(id=>$(id).disabled=false);playing(true);if(remember&&db)try{await storage('roms','put',current)}catch(e){toast('Playing, but could not keep the cartridge: '+e.message,true)}await renderLibrary();await renderSlots();if(current.demo)toast('Star Circuit: arrows to fly, X to boost. Collect the gold stars!');$('screen').focus({preventScroll:true})}catch(e){toast('Could not load cartridge: '+e.message,true);if(nes)playing(oldRunning)}finally{loading=false}}
async function loadFiles(files){for(const file of files)try{if(file.size>16*1024*1024)throw new Error('NES cartridge files must be smaller than 16 MB.');const data=await file.arrayBuffer();validateROM(data);await loadCartridge({id:romId(data),name:file.name.replace(/\.nes$/i,''),data})}catch(e){toast(e.message,true)}}
async function renderLibrary(){if(!db){$('cartridges').innerHTML='<div class="empty"><p>Load a cartridge to play</p><small>Browser storage is unavailable.</small></div>';return}const records=(await storage('roms','getAll')).sort((a,b)=>b.lastPlayed-a.lastPlayed);$('count').textContent=String(records.length).padStart(2,'0');$('cartridges').replaceChildren();if(!records.length){$('cartridges').innerHTML='<div class="empty"><span>▤</span><p>No cartridges yet</p><small>Load a game from your device.<br>It stays right here in your browser.</small></div>';return}for(const rec of records){const row=document.createElement('div');row.className='cart'+(current?.id===rec.id?' active':'');const art=document.createElement('span');art.textContent=rec.demo?'★':'8';const play=document.createElement('button');play.className='cart-play';play.title='Play '+rec.name;const title=document.createElement('strong');title.textContent=rec.name;const info=document.createElement('small');info.textContent=rec.demo?'ORIGINAL DEMO':`${Math.round(rec.data.byteLength/1024)} KB · MAPPER ${rec.mapper}`;play.append(title,info);play.onclick=()=>loadCartridge(rec);const remove=document.createElement('button');remove.className='remove';remove.textContent='×';remove.setAttribute('aria-label','Remove '+rec.name+' from cartridges');remove.onclick=async()=>{if(!confirm(`Remove ${rec.name} from this browser’s cartridge list? Save slots will stay.`))return;try{await storage('roms','delete',rec.id);await renderLibrary();toast('Cartridge removed. Save slots kept.')}catch(e){toast(e.message,true)}};row.append(art,play,remove);$('cartridges').append(row)}}
async function renderSlots(){const id=current?.id;slots=[];for(let n=1;n<=3;n++){const rec=db&&id?await storage('states','get',`${id}:${n}`):null;if(current?.id!==id)return;slots.push(rec)}$('slots').replaceChildren();slots.forEach((rec,i)=>{const n=i+1,row=document.createElement('div');row.className='slot';const pic=document.createElement(rec?.image?'img':'div');pic.className='slot-preview';if(rec?.image){pic.src=rec.image;pic.alt=`Slot ${n} screenshot`}else pic.textContent=String(n).padStart(2,'0');const info=document.createElement('div');info.className='slot-info';const title=document.createElement('strong');title.textContent=`Slot ${n}`;const date=document.createElement('small');date.textContent=rec?new Date(rec.updated).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'EMPTY';info.append(title,date);const actions=document.createElement('div');actions.className='slot-actions';const save=document.createElement('button');save.textContent='Save';save.setAttribute('aria-label',`Save to slot ${n}`);save.disabled=!current||!db;save.onclick=()=>saveSlot(n);const load=document.createElement('button');load.textContent='Load';load.setAttribute('aria-label',`Load slot ${n}`);load.disabled=!rec;load.onclick=()=>restore(rec);actions.append(save,load);row.append(pic,info,actions);$('slots').append(row)})}
function snapshot(){if(!current||!nes)throw new Error('Load a cartridge first.');return {format:'drews-8bit-state',version:1,core:CORE,romId:current.id,game:current.name,updated:Date.now(),state:nes.toJSON(),image:canvas.toDataURL('image/png')}}
