function restore(s){try{if(s?.format!=='drews-8bit-state'||s.version!==1||s.core!==CORE)throw new Error('This is not a compatible save state.');if(s.romId!==current?.id)throw new Error('Load the matching cartridge before restoring this save.');for(const k of ['cpu','ppu','papu','mmap'])if(!s.state?.[k]||typeof s.state[k]!=='object')throw new Error('The save state is incomplete.');if(!Array.isArray(s.state.cpu.mem)||s.state.cpu.mem.length!==65536)throw new Error('The save memory is invalid.');const candidate=createNES(current.data);candidate.fromJSON(s.state);playing(false);nes=candidate;dirty=true;playing(true);toast('Save restored.');$('screen').focus({preventScroll:true})}catch(e){toast('Could not restore: '+e.message,true)}}
$('export').onclick=()=>{try{const data=JSON.stringify(snapshot()),url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=current.name.replace(/[^a-z0-9_-]/gi,'_')+'-state.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Current state exported. Keep it with your ROM.')}catch(e){toast(e.message,true)}};
$('import').onclick=()=>$('state-file').click();$('state-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>20*1024*1024)throw new Error('Save file is too large.');restore(JSON.parse(await file.text()))}catch(e){toast('Could not read save file: '+e.message,true)}};
['load','load-screen'].forEach(id=>$(id).onclick=()=>{initAudio();$('rom-file').click()});$('rom-file').onchange=e=>{const files=[...e.target.files];e.target.value='';loadFiles(files)};
$('demo').onclick=async()=>{initAudio();try{const r=await fetch('star-circuit.nes');if(!r.ok)throw new Error('Demo is unavailable.');const data=await r.arrayBuffer();await loadCartridge({id:romId(data),name:'Star Circuit',data,demo:true})}catch(e){toast(e.message,true)}};
$('pause').onclick=pause;$('resume').onclick=pause;$('reset').onclick=()=>{if(current&&confirm('Restart this cartridge? Unsaved progress will be lost.'))loadCartridge(current,false)};
$('mute').onclick=()=>{settings.muted=!settings.muted;volume()};$('volume').oninput=e=>{settings.volume=Number(e.target.value);settings.muted=false;volume()};volume();
$('crt').checked=settings.crt;function crt(){settings.crt=$('crt').checked;$('scanlines').classList.toggle('hidden',!settings.crt);rememberSettings()}$('crt').onchange=crt;crt();
function touch(){ $('touch').classList.toggle('hidden',!settings.touch);$('touch-toggle').textContent=settings.touch?'Hide touch controls':'Show touch controls';$('touch-toggle').setAttribute('aria-expanded',String(settings.touch));rememberSettings()}$('touch-toggle').onclick=()=>{settings.touch=!settings.touch;touch()};touch();
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else if($('tv').requestFullscreen)await $('tv').requestFullscreen();else toast('Fullscreen is unavailable. Rotate your device for a larger view.')}catch{toast('Open the player in its own browser tab to use fullscreen.',true)}}$('fullscreen').onclick=fullscreen;
function help(){if(running)playing(false);$('help-dialog').showModal()}['help','all-controls','about'].forEach(id=>$(id).onclick=help);$('close-help').onclick=()=>$('help-dialog').close();
const keys={ArrowUp:[1,4],ArrowDown:[1,5],ArrowLeft:[1,6],ArrowRight:[1,7],KeyX:[1,0],KeyZ:[1,1],ShiftLeft:[1,2],ShiftRight:[1,2],Enter:[1,3],KeyS:[1,8],KeyA:[1,9],Numpad8:[2,4],Numpad2:[2,5],Numpad4:[2,6],Numpad6:[2,7],Numpad7:[2,0],Numpad9:[2,1],Numpad1:[2,3],Numpad3:[2,2]};
const editing=e=>/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable||$('help-dialog').open;
document.addEventListener('keydown',e=>{if(editing(e)||e.metaKey||e.ctrlKey||e.altKey)return;if(keys[e.code]&&running){e.preventDefault();pressed.set('key'+e.code,keys[e.code].join(':'))}else if(!e.repeat&&['KeyP','KeyF','KeyM'].includes(e.code)){e.preventDefault();if(e.code==='KeyP')pause();if(e.code==='KeyF')fullscreen();if(e.code==='KeyM')$('mute').click()}});document.addEventListener('keyup',e=>{if(keys[e.code]){pressed.delete('key'+e.code);if(running&&!editing(e))e.preventDefault()}});
document.querySelectorAll('[data-pad]').forEach(button=>{button.addEventListener('pointerdown',e=>{e.preventDefault();if(!running)return;button.setPointerCapture(e.pointerId);pressed.set('touch'+e.pointerId,'1:'+button.dataset.pad);button.classList.add('held')});const end=e=>{pressed.delete('touch'+e.pointerId);button.classList.remove('held')};['pointerup','pointercancel','lostpointercapture'].forEach(name=>button.addEventListener(name,end))});
window.addEventListener('blur',()=>{release();if(running)playing(false)});document.addEventListener('visibilitychange',()=>{if(document.hidden&&running)playing(false)});window.addEventListener('pagehide',()=>saveBattery().catch(()=>{}));setInterval(()=>saveBattery().catch(e=>toast(e.message,true)),5000);
